// ABOUTME: Property tests for the aggregation operators, generated by a seeded fast-check run so a
// ABOUTME: failure reproduces: a sum ignores order, a best_n never overfills or drops a satisfiable
// ABOUTME: group minimum, a mean of equal values is that value, a weighted mean ignores a common
// ABOUTME: rescaling, and every result replays from its own trace.

import * as fc from 'fast-check';
import { describe, it } from 'vitest';

import { evaluateAggregation, rankLearners, replayAggregate } from '..';
import type { AggregateResult, AggregateTrace, AggregationDefinition, LearningAreaResult } from '..';

const OPTIONS = { seed: 20261021, numRuns: 120 } as const;

const CODES = ['A', 'B', 'C', 'D', 'E', 'F'] as const;

const area = fc.record({
  code: fc.constantFrom(...CODES),
  group: fc.constantFrom('sci', 'art'),
  points: fc.integer({ min: 0, max: 12 }).map(String),
  coefficient: fc.integer({ min: 1, max: 5 }).map(String),
  rubric_level: fc.integer({ min: 1, max: 4 }).map(String),
  grade: fc.constantFrom('EE', 'ME', 'AE', 'BE'),
});

const areas = fc.uniqueArray(area, { selector: (entry) => entry.code, minLength: 1, maxLength: 6 });

function run(definition: AggregationDefinition, inputs: readonly LearningAreaResult[]): AggregateResult {
  const evaluation = evaluateAggregation(definition, inputs);
  if (!evaluation.ok) throw new Error(`unexpected issues: ${evaluation.issues.map((entry) => entry.code).join(', ')}`);
  return evaluation.result;
}

const SUM: AggregationDefinition = { code: 'sum', op: 'sum', value: 'points' };
const MEAN: AggregationDefinition = { code: 'mean', op: 'mean', value: 'score' };
const WEIGHTED: AggregationDefinition = { code: 'weighted', op: 'weighted_mean', value: 'points', weights: 'coefficient' };
const COUNT: AggregationDefinition = { code: 'count', op: 'count_where', value: 'grade', where: { op: 'in', values: ['EE', 'ME'] } };

function pointsAreas(inputs: readonly LearningAreaResult[]): readonly LearningAreaResult[] {
  return inputs.map((entry) => ({ code: entry.code, group: entry.group, points: entry.points, coefficient: entry.coefficient }));
}

describe('sum', () => {
  it('is order-independent', () => {
    fc.assert(
      fc.property(areas, (entries) => {
        const forward = run(SUM, entries).value;
        const backward = run(SUM, [...entries].reverse()).value;
        const rotated = run(SUM, [...entries.slice(1), entries[0]]).value;
        return forward === backward && forward === rotated;
      }),
      OPTIONS
    );
  });
});

describe('mean', () => {
  it('of identical values is that value', () => {
    fc.assert(
      fc.property(fc.integer({ min: 0, max: 2000 }), fc.integer({ min: 1, max: 6 }), (raw, count) => {
        const value = `${Math.floor(raw / 100)}.${String(raw % 100).padStart(2, '0')}`;
        const inputs: LearningAreaResult[] = CODES.slice(0, count).map((code) => ({ code, score: value }));
        return run(MEAN, inputs).value === String(Number(value));
      }),
      OPTIONS
    );
  });
});

describe('weighted_mean', () => {
  it('ignores a common rescaling of every weight', () => {
    fc.assert(
      fc.property(areas, (entries) => {
        const base = pointsAreas(entries);
        const doubled = base.map((entry) => ({
          ...entry,
          coefficient: String(Number(entry.coefficient) * 2),
        }));
        return run(WEIGHTED, base).value === run(WEIGHTED, doubled).value;
      }),
      OPTIONS
    );
  });
});

describe('best_n', () => {
  const definition = (n: number): AggregationDefinition => ({
    code: 'best',
    op: 'best_n',
    n,
    value: 'points',
    groups: [{ group: 'sci', min: 2 }, { fill_from: 'any' }],
  });

  const guaranteed = (values: readonly number[], extra: readonly LearningAreaResult[]): readonly LearningAreaResult[] => [
    { code: 'S1', group: 'sci', points: String(values[0]) },
    { code: 'S2', group: 'sci', points: String(values[1]) },
    ...extra.map((entry) => ({ ...entry, group: 'art' })),
  ];

  const extras = fc.uniqueArray(fc.integer({ min: 0, max: 12 }), { minLength: 0, maxLength: 4 });

  it('never selects more than n, and fills n when the candidates allow it', () => {
    fc.assert(
      fc.property(
        fc.tuple(fc.integer({ min: 0, max: 12 }), fc.integer({ min: 0, max: 12 })),
        extras,
        (values, raw) => {
          const inputs = guaranteed(values, raw.map((points, index) => ({ code: `X${index}`, group: 'art', points: String(points) })));
          const n = 2 + (raw.length === 0 ? 0 : Math.abs(values[0] + raw[0]) % (raw.length + 1));
          const result = run(definition(n), inputs);
          if ((result.selected?.length ?? 0) > n) return false;
          return result.selected?.length === Math.min(n, inputs.length);
        }
      ),
      { ...OPTIONS, numRuns: 60 }
    );
  });

  it('keeps the group minimum whenever the candidates can satisfy it', () => {
    fc.assert(
      fc.property(
        fc.tuple(fc.integer({ min: 0, max: 12 }), fc.integer({ min: 0, max: 12 })),
        extras,
        (values, raw) => {
          const inputs = guaranteed(
            values,
            raw.map((points, index) => ({ code: `X${index}`, group: 'art', points: String(points) }))
          );
          const result = run(definition(5), inputs);
          const fromSciences = (result.selected ?? []).filter((code) => code === 'S1' || code === 'S2');
          return fromSciences.length === 2;
        }
      ),
      { ...OPTIONS, numRuns: 60 }
    );
  });
});

describe('the trace', () => {
  const definitions: readonly AggregationDefinition[] = [
    SUM,
    { code: 'mean_points', op: 'mean', value: 'points', precision: 2 },
    WEIGHTED,
    COUNT,
    {
      code: 'best',
      op: 'best_n',
      n: 3,
      value: 'points',
      groups: [{ require_all: ['A'] }, { fill_from: 'any' }],
      then: { op: 'mean', precision: 3 },
    },
  ];

  it('replays a result into its own value and reproduces it from the recorded inputs', () => {
    fc.assert(
      fc.property(areas, (entries) => {
        for (const definition of definitions) {
          const result = run(definition, entries);
          const replayed = replayAggregate(JSON.parse(JSON.stringify(result.trace)) as AggregateTrace);
          if (replayed.value !== result.value) return false;
          const again = evaluateAggregation(result.trace.definition, result.trace.inputs);
          if (!again.ok) return false;
          if (again.result.value !== result.value) return false;
        }
        return true;
      }),
      OPTIONS
    );
  });
});

describe('multipliers', () => {
  const definition: AggregationDefinition = {
    code: 'attainment',
    op: 'best_n',
    n: 3,
    value: 'points',
    groups: [{ require_all: ['A'] }, { fill_from: 'any' }],
    then: { op: 'sum' },
    multipliers: { A: 2 },
    divisor: 'sum_of_multipliers',
  };

  it('replays a multiplied result, its divisor and its per-part products', () => {
    fc.assert(
      fc.property(areas, (entries) => {
        // A is compulsory, so the multiplier always has an area to apply to
        const withA: readonly LearningAreaResult[] = [
          { code: 'A', group: 'sci', points: '10' },
          ...entries.filter((entry) => entry.code !== 'A'),
        ];
        const result = run(definition, withA);
        const replayed = replayAggregate(JSON.parse(JSON.stringify(result.trace)) as AggregateTrace);
        if (replayed.value !== result.value) return false;
        const step = result.trace.steps.find((entry) => entry.kind === 'sum');
        if (step?.kind !== 'sum') return false;
        const doubles = step.parts.filter((part) => part.multiplier === '2').map((part) => part.code);
        if (doubles.length !== 1 || doubles[0] !== 'A') return false;
        const again = evaluateAggregation(result.trace.definition, result.trace.inputs);
        return again.ok && again.result.value === result.value;
      }),
      OPTIONS
    );
  });
});

describe('ranking', () => {
  it('keeps positions non-decreasing down the ranked list and counts only the ranked', () => {
    fc.assert(
      fc.property(
        fc.uniqueArray(
          fc.record({
            learner: fc.integer({ min: 1, max: 40 }).map((value) => `L${String(value).padStart(2, '0')}`),
            value: fc.integer({ min: 0, max: 100 }).map(String),
            complete: fc.boolean(),
          }),
          { selector: (entry) => entry.learner, minLength: 1, maxLength: 8 }
        ),
        fc.constantFrom('competition_1224' as const, 'dense_1223' as const, 'shared_average' as const),
        (entries, ties) => {
          const ranking = rankLearners(
            { enabled: true, scope: 'class_group', by: 'mean', ties, only_complete: true },
            entries.map((entry) => ({ ...entry, scope: 'F4A' }))
          );
          if (!ranking.ok) return false;
          const ranked = ranking.result.entries.filter((entry) => entry.ranked);
          const positions = ranked.map((entry) => Number(entry.position));
          const ordered = positions.every((position, index) => index === 0 || position >= positions[index - 1]);
          const counted = ranked.every((entry) => entry.out_of === ranked.length);
          const listed = ranking.result.entries.length === entries.length;
          return ordered && counted && listed;
        }
      ),
      OPTIONS
    );
  });
});
